<script setup>
import { Head, router, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import Icon from '../../../Components/Icon.vue';

const props = defineProps({
    reels: { type: Array, default: () => [] },
    products: { type: Array, default: () => [] },
    services: { type: Array, default: () => [] },
    view: { type: String, default: 'active' },
    counts: { type: Object, default: () => ({}) },
});

const editingId = ref(null);
const mediaPreview = ref('');
const coverPreview = ref('');
const trash = computed(() => props.view === 'trash');

const form = useForm({ item_type: 'product', item_id: '', title: '', caption: '', media_type: 'image', media_file: null, external_url: '', cover_image_file: null, cta_label: '', display_seconds: 6, sort_order: 0, is_active: true });
const items = computed(() => form.item_type === 'product' ? props.products : props.services);
const selectedItem = computed(() => items.value.find((item) => Number(item.id) === Number(form.item_id)) || null);
const previewTitle = computed(() => form.title || selectedItem.value?.name || 'Select an item');
const previewCaption = computed(() => form.caption || selectedItem.value?.short_description || 'Add a short caption for the reel.');
const previewCover = computed(() => coverPreview.value || (form.media_type === 'image' ? mediaPreview.value : '') || selectedItem.value?.image_url || '/assets/accessory.svg');
const previewMedia = computed(() => mediaPreview.value || form.external_url || (form.media_type === 'image' ? selectedItem.value?.image_url : '') || '');
function switchItemType(type){if(form.item_type===type)return;form.item_type=type;form.item_id='';form.clearErrors('item_id')}
function switchMediaType(type){if(form.media_type===type)return;form.media_type=type;form.media_file=null;form.external_url='';mediaPreview.value='';form.clearErrors('media_file','external_url')}
function onMediaFile(event){const file=event.target.files?.[0]||null;form.media_file=file;mediaPreview.value=file?URL.createObjectURL(file):''}
function onCoverFile(event){const file=event.target.files?.[0]||null;form.cover_image_file=file;coverPreview.value=file?URL.createObjectURL(file):''}
function resetForm(){editingId.value=null;mediaPreview.value='';coverPreview.value='';form.reset();form.item_type='product';form.item_id='';form.media_type='image';form.display_seconds=6;form.sort_order=props.reels.length;form.is_active=true;form.clearErrors()}
function editReel(reel){editingId.value=reel.id;form.item_type=reel.item_type;form.item_id=reel.item_type==='product'?reel.product_id:reel.service_id;form.title=reel.title||'';form.caption=reel.caption||'';form.media_type=reel.media_type||'image';form.media_file=null;form.external_url=reel.external_url||'';form.cover_image_file=null;form.cta_label=reel.cta_label||'';form.display_seconds=reel.display_seconds||6;form.sort_order=reel.sort_order??0;form.is_active=Boolean(reel.is_active);mediaPreview.value=reel.media_url||'';coverPreview.value=reel.cover_url||'';form.clearErrors();window.scrollTo({top:0,behavior:'smooth'})}
function save(){form.post(editingId.value?`/admin/reels/${editingId.value}`:'/admin/reels',{preserveScroll:true,forceFormData:true,onSuccess:resetForm})}
function removeReel(reel){if(confirm(`Move “${reel.title||reelItem(reel)?.name||'this reel'}” to Trash?`))router.delete(`/admin/reels/${reel.id}`,{preserveScroll:true})}
function restoreReel(reel){router.post(`/admin/reels/${reel.id}/restore`,{},{preserveScroll:true})}
function switchView(view){router.get('/admin/reels',{view:view||undefined},{preserveState:true,replace:true})}
function reelItem(reel){return reel.item_type==='service'?reel.service:reel.product}
function money(value){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(value||0))}
</script>

<template>
    <AdminLayout>
        <Head title="Product Reels" />
        <div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="section-kicker">Short-form showcase</p><h1 class="section-title">Product reels</h1><p class="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Publish vertical product videos or images that customers can swipe through on the homepage.</p></div><button class="btn-light self-start" type="button" @click="switchView(trash ? '' : 'trash')">{{ trash ? 'Back to reels' : `Trash (${counts.trash || 0})` }}</button></div>

        <div v-if="!trash" class="mt-7 grid gap-6 xl:grid-cols-[410px_1fr]">
            <section class="card h-fit overflow-hidden xl:sticky xl:top-24"><div class="border-b border-slate-200 bg-slate-50 px-5 py-4"><p class="text-[10px] font-black uppercase tracking-[.16em] text-prinx-600">{{ editingId ? 'Editing reel' : 'New reel' }}</p><h2 class="mt-1 text-lg font-black text-slate-950">{{ editingId ? 'Update reel' : 'Create a reel' }}</h2></div><form class="space-y-4 p-5" @submit.prevent="save">
                <div><label class="label">Item type</label><div class="grid grid-cols-2 gap-2"><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', form.item_type === 'product' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="switchItemType('product')">Product</button><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', form.item_type === 'service' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="switchItemType('service')">Service</button></div></div>
                <div><label class="label">Select {{ form.item_type }} *</label><select v-model="form.item_id" class="input"><option value="">Choose an item</option><option v-for="item in items" :key="item.id" :value="item.id">{{ item.name }}</option></select><p class="error">{{ form.errors.item_id }}</p></div>
                <div><label class="label">Reel title</label><input v-model="form.title" class="input" maxlength="160" :placeholder="selectedItem?.name || 'Uses the item name when empty'"><p class="error">{{ form.errors.title }}</p></div>
                <div><label class="label">Short caption</label><textarea v-model="form.caption" class="input" rows="3" maxlength="800" placeholder="A clear benefit, offer or instruction."></textarea><p class="error">{{ form.errors.caption }}</p></div>
                <div><label class="label">Reel format</label><div class="grid grid-cols-2 gap-2"><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', form.media_type === 'image' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="switchMediaType('image')">Image reel</button><button type="button" :class="['rounded-[9px] border px-3 py-2.5 text-sm font-black', form.media_type === 'video' ? 'border-prinx-500 bg-prinx-50 text-prinx-700' : 'border-slate-200 text-slate-500']" @click="switchMediaType('video')">Video reel</button></div></div>
                <div><label class="label">Upload {{ form.media_type }}</label><input type="file" class="input" :accept="form.media_type === 'video' ? 'video/mp4,video/webm,video/quicktime' : 'image/jpeg,image/png,image/webp'" @change="onMediaFile"><p class="image-spec">Recommended: 1080 × 1920 px (9:16). {{ form.media_type === 'video' ? 'MP4/WebM/MOV, maximum 50 MB.' : 'JPG/PNG/WebP, maximum 8 MB. Images are converted to WebP.' }}</p><p class="error">{{ form.errors.media_file }}</p></div>
                <div><label class="label">Direct media URL</label><input v-model="form.external_url" type="url" class="input" :placeholder="form.media_type === 'video' ? 'https://.../reel.mp4' : 'https://.../image.webp'"><p class="image-spec">Optional. Use a direct image or video-file URL, not a social-media page link.</p><p class="error">{{ form.errors.external_url }}</p></div>
                <div v-if="form.media_type === 'video'"><label class="label">Video cover image</label><input type="file" class="input" accept="image/jpeg,image/png,image/webp" @change="onCoverFile"><p class="image-spec">Recommended: 1080 × 1920 px (9:16), maximum 8 MB.</p><p class="error">{{ form.errors.cover_image_file }}</p></div>
                <div class="grid gap-3 sm:grid-cols-2"><div><label class="label">Button label</label><input v-model="form.cta_label" class="input" :placeholder="form.item_type === 'product' ? 'View product' : 'View service'"></div><div v-if="form.media_type === 'image'"><label class="label">Seconds</label><input v-model="form.display_seconds" type="number" min="3" max="15" class="input"><p class="error">{{ form.errors.display_seconds }}</p></div></div>
                <div class="grid grid-cols-2 gap-3"><div><label class="label">Display order</label><input v-model="form.sort_order" type="number" min="0" max="9999" class="input"><p class="error">{{ form.errors.sort_order }}</p></div><label class="mt-7 flex items-center gap-2 text-sm font-bold text-slate-700"><input v-model="form.is_active" type="checkbox" class="h-4 w-4 accent-prinx-500"> Published</label></div>
                <div class="mx-auto w-full max-w-[220px] overflow-hidden rounded-[10px] border border-slate-200 bg-slate-950 shadow-xl"><div class="relative aspect-[9/16] overflow-hidden"><template v-if="form.media_type === 'video' && previewMedia"><video :src="previewMedia" :poster="previewCover" class="absolute inset-0 h-full w-full object-cover" muted playsinline></video><div class="absolute inset-0 flex items-center justify-center bg-black/20"><span class="flex h-12 w-12 items-center justify-center rounded-full bg-white/90 text-slate-950"><Icon name="play" :size="22" /></span></div></template><img v-else :src="previewCover" :alt="previewTitle" :class="['absolute inset-0 h-full w-full', form.media_type === 'image' ? 'object-contain p-4' : 'object-cover']"><div v-if="form.media_type === 'video' && !previewMedia" class="absolute inset-0 flex items-center justify-center bg-black/20"><span class="flex h-12 w-12 items-center justify-center rounded-full bg-white/90 text-slate-950"><Icon name="play" :size="22" /></span></div><div class="absolute inset-0 bg-gradient-to-t from-black via-black/10 to-black/20"></div><div class="absolute inset-x-0 bottom-0 p-4 text-white"><p class="text-[9px] font-black uppercase tracking-[.14em] text-prinx-300">Prinx reel</p><h3 class="mt-1 line-clamp-2 text-base font-black">{{ previewTitle }}</h3><p class="mt-1 line-clamp-2 text-[11px] leading-4 text-white/70">{{ previewCaption }}</p></div></div></div>
                <button class="btn-primary w-full py-3" :disabled="form.processing">{{ form.processing ? 'Saving...' : editingId ? 'Save reel' : 'Publish reel' }}</button><button v-if="editingId" type="button" class="w-full text-sm font-bold text-slate-500 hover:text-prinx-600" @click="resetForm">Cancel editing</button>
            </form></section>

            <section><div class="mb-4 flex items-center justify-between gap-4"><div><h2 class="text-lg font-black text-slate-950">Published reel sequence</h2><p class="mt-1 text-xs text-slate-500">Lower display-order numbers appear first.</p></div><span class="status bg-prinx-50 text-prinx-700">{{ reels.length }} reels</span></div><div class="grid gap-4 sm:grid-cols-2 2xl:grid-cols-3"><article v-for="(reel,index) in reels" :key="reel.id" class="card overflow-hidden"><div class="relative aspect-[9/11] overflow-hidden bg-slate-950"><img :src="reel.cover_url" :alt="reel.title || reelItem(reel)?.name" :class="['h-full w-full', reel.media_type === 'image' ? 'object-contain bg-[radial-gradient(circle_at_50%_35%,#fff7ed,#fed7aa_42%,#0f172a)] p-5' : 'object-cover']"><div class="absolute inset-0 bg-gradient-to-t from-black via-transparent to-black/10"></div><span class="absolute left-3 top-3 rounded-[8px] bg-slate-950/80 px-2.5 py-1 text-[9px] font-black uppercase tracking-[.14em] text-white">{{ String(index + 1).padStart(2, '0') }}</span><span class="absolute right-3 top-3 rounded-[8px] bg-white/90 px-2.5 py-1 text-[9px] font-black uppercase tracking-[.14em] text-slate-950">{{ reel.media_type }}</span><div class="absolute inset-x-0 bottom-0 p-4 text-white"><p class="text-[9px] font-black uppercase tracking-[.14em] text-prinx-300">{{ reel.item_type }} · Order {{ reel.sort_order }}</p><h3 class="mt-1 line-clamp-2 text-lg font-black">{{ reel.title || reelItem(reel)?.name }}</h3><p class="mt-2 text-xs font-black">{{ reel.item_type === 'product' ? money(reel.product?.current_price || reel.product?.price) : (reel.service?.price_label || 'Request a quote') }}</p></div></div><div class="p-4"><div class="flex items-center justify-between gap-3"><span :class="['status', reel.is_active ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500']">{{ reel.is_active ? 'Published' : 'Hidden' }}</span><span class="text-xs font-bold text-slate-400">{{ reel.media_type === 'image' ? `${reel.display_seconds}s` : 'Auto play' }}</span></div><p v-if="reel.caption" class="mt-3 line-clamp-2 text-sm leading-6 text-slate-500">{{ reel.caption }}</p><div class="mt-4 flex justify-end gap-2 border-t border-slate-100 pt-4"><button class="btn-light px-3 py-2" @click="editReel(reel)">Edit</button><button class="btn-danger" @click="removeReel(reel)">Delete</button></div></div></article><div v-if="!reels.length" class="card col-span-full py-20 text-center"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-[10px] bg-prinx-50 text-prinx-600"><Icon name="video-play" :size="25" /></div><p class="mt-4 font-black text-slate-800">No reels published</p><p class="mt-1 text-sm text-slate-500">Create the first product or service reel.</p></div></div></section>
        </div>

        <section v-else class="mt-7"><div class="rounded-[10px] border border-red-200 bg-red-50 p-5"><h2 class="font-black text-red-900">Reels Trash</h2><p class="mt-1 text-sm text-red-700">Deleted reels can be restored.</p></div><div class="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article v-for="reel in reels" :key="reel.id" class="card overflow-hidden p-4"><div class="flex items-center gap-3"><img :src="reel.cover_url" :alt="reel.title || reelItem(reel)?.name" class="h-20 w-14 rounded-[8px] border border-slate-200 object-cover"><div class="min-w-0"><p class="truncate font-black text-slate-900">{{ reel.title || reelItem(reel)?.name || 'Unavailable item' }}</p><p class="mt-1 text-xs text-slate-500">Deleted {{ new Date(reel.deleted_at).toLocaleString() }}</p></div></div><button class="btn-primary mt-4 w-full" @click="restoreReel(reel)">Restore reel</button></article><div v-if="!reels.length" class="card col-span-full py-16 text-center text-sm font-semibold text-slate-500">Reels Trash is empty.</div></div></section>
    </AdminLayout>
</template>
